    // Constants
    constexpr double PI = 3.14159265358979323846;
    constexpr double EPSILON = 1e-15;
    constexpr double MAX_ITERATIONS = 1000;

    // Helper functions for complex logarithm with correct branch handling
    std::complex<double> complex_log(const std::complex<double>& z) {
        // Use std::log for complex logarithm which handles branch cuts correctly
        return std::log(z);
    }

    // Fourier inversion for Heston call option
    std::complex<double> heston_char_function(double u, double T, const Heston& h, double r, double q) {
        // Heston characteristic function
        double d = std::sqrt(h.kappa * h.kappa - h.xi * h.xi);
        double phi = h.kappa - h.rho * h.xi * u;
        double phi2 = phi * phi;
        double xi2 = h.xi * h.xi;
        double d2 = d * d;

        // Avoid division by zero
        if (std::abs(d) < EPSILON) {
            d = EPSILON;
        }

        double a = (h.kappa * h.theta - r + q) * u * 1i;
        double b = h.kappa * h.theta - r + q;
        double c = h.xi * h.xi * u * u;

        // Compute the characteristic function
        std::complex<double> numerator = std::exp((b + d) * T / 2) - std::exp((b - d) * T / 2);
        std::complex<double> denominator = (b + d) * std::exp((b + d) * T / 2) - (b - d) * std::exp((b - d) * T / 2);

        // Handle the case where denominator is very small
        if (std::abs(denominator) < EPSILON) {
            denominator = std::complex<double>(EPSILON, 0);
        }

        std::complex<double> exp_term = std::exp(h.v0 * (b + d) * T / 2);
