        return char_func;
    }

    // Heston pricing using Fourier inversion method
    double heston_call_fourier(double S, double K, double r, double q, double T, const Heston& h) {
        // Use the Lewis (2000) approach for numerical integration
        // The integral is: C = S * P1 - K * exp(-r*T) * P2
        // where P1 and P2 are probabilities computed via Fourier inversion

        // Integration parameters
        const int N = 1000;
        const double b = 100.0;  // Integration limit
        const double dx = b / N;

        // Compute the characteristic function for the call option
        std::complex<double> integral_sum = 0.0;

        // Use the standard Fourier inversion formula
        for (int i = 0; i < N; i++) {
            double u = (i + 0.5) * dx;
            std::complex<double> iu = std::complex<double>(0, u);

            // Compute the characteristic function
            std::complex<double> char_func = heston_char_function(u, T, h, r, q);

            // Compute the integrand
            std::complex<double> integrand = std::exp(-iu * std::log(K)) * char_func / (iu * (iu + 1i));

            integral_sum += integrand;
