            std::complex<double> numerator = std::exp((phi + d) * T / 2) - std::exp((phi - d) * T / 2);
            std::complex<double> denominator = (phi + d) * std::exp((phi + d) * T / 2) - (phi - d) * std::exp((phi - d) * T / 2);

            // Handle small denominator
