            std::complex<double> integrand = std::exp(-iu * std::log(K)) * char_func / (iu * (iu + 1i));

            sum_real += integrand.real();
            sum_imag += integrand.imag();
        }

        // Apply the trapezoidal rule and scaling
        double integral_real = sum_real * dx;
